type TimedRow = { time: number; seq: number };

function getSortedCopy(rows: TimedRow[]): TimedRow[] {
  return [...rows].sort((a, b) => (a.time < b.time ? -1 : a.time > b.time ? 1 : 0));
}

const input: TimedRow[] = [
  { time: 50, seq: 1 },
  { time: 10, seq: 2 },
  { time: 50, seq: 3 },
];
const copy = getSortedCopy(input);

// Original array remains untouched, and equal times return 0 to preserve relative order
console.assert(input[0].time === 50 && input[1].time === 10);
console.assert(copy[0].time === 10 && copy[1].seq === 1 && copy[2].seq === 3);
